import type {Match} from "./types";
export type Lang="ar"|"fr"|"en";
export const LANGS:Lang[]=["ar","fr","en"];
export const LANG_COOKIE="hadaf_lang";
export const isLang=(x:unknown):x is Lang=>x==="ar"||x==="fr"||x==="en";
export const dirOf=(l:Lang)=>l==="ar"?"rtl":"ltr";
export const locOf=(l:Lang)=>l==="ar"?"ar-DZ":l==="fr"?"fr-FR":"en-GB";
/** اسم الدوري: بالعربية للعربية، والاسم الأصلي للباقي */
export const leagueOf=(m:Pick<Match,"league"|"leagueRaw">,l:Lang)=>l==="ar"?m.league:(m.leagueRaw||m.league);

